{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine has a mean systemic availability of 16.5% in healthy volunteers, below the 20% threshold; although structurally distant from the polyisoprenyl quinone, it is a lipophilic drug with low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine absolute oral bioavailability is 18% in healthy subjects, below the 20% threshold; this is structurally distant but provides weak analogical support for low F in a lipophilic small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib absolute oral bioavailability is only 13.9% in the fed state, below the threshold, illustrating that oral F can be strongly formulation/condition-dependent; the query has no formulation context and is far more lipophilic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nifedipine has an absolute oral bioavailability of 0.43 ± 0.14 in humans, above the threshold; this is contradictory direction but from a small dihydropyridine with little structural or physicochemical transfer to ubiquinone-9.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Ubiquinone-9 is an extremely lipophilic, high-molecular-weight polyisoprenyl benzoquinone; established coenzyme Q behavior and physicochemical properties indicate poor oral absorption, and the available structurally distant records do not provide transferable evidence for F ≥ 20%. Prediction: low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-9/CoQ9 in the provided records.",
    "No formulation, fed/fasted, or dose conditions are specified for the query; CoQ absorption is strongly formulation-dependent.",
    "All provided records are structurally distant small drug-like molecules; none share the polyisoprenyl quinone core."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

